def solve_n4(x):
    lhs = x**4 + x
    rhs_minus_2 = lhs - 2
    k = 0
    if rhs_minus_2 > 0:
        temp = rhs_minus_2
        while temp > 1 and temp % 2 == 0:
            temp //= 2
            k += 1

    if temp == 1:
        return (x, 4, k)
    return None

solutions = []
for x in range(5, 21): # Search x > 4 up to 20
    solution = solve_n4(x)
    if solution:
        solutions.append(solution)

print(solutions)

